func (s *Store) readLocked(fn func(*persistedState) error) error {
	unlock, err := s.lock()
	if err != nil { return err }
	defer unlock()
	state, err := s.readState()
	if err != nil { return err }
	return fn(state)
}

func (s *Store) writeLocked(fn func(*persistedState) error) error {
	unlock, err := s.lock()
	...
	state, err := s.readState()
	if err != nil { return err }
	if err := fn(state); err != nil { return err }
	return s.writeState(state)
}
```

