func sameProposalContent(a, b Proposal) bool {
	if a.Title != b.Title || a.ForVotes != b.ForVotes || a.AgainstVotes != b.AgainstVotes ||
		a.Quorum != b.Quorum || a.TimelockEnd != b.TimelockEnd {
