```go
func (s *Store) Execute(proposalID string, now int64) (*Receipt, error) {
	if strings.TrimSpace(proposalID) == "" {
		return nil, fmt.Errorf("%w: proposal id must not be empty", ErrInvalidArg)
	}
	var receipt *Receipt
	err := s.writeLocked(func(state *persistedState) error {
		prop, ok := state.Proposals[proposalID]
		if !ok {
			return fmt.Errorf("%w: proposal %q is not registered", ErrNotFound, proposalID)
		}
		if prop.State == "executed" {
			r := findReceipt(state, proposalID)
			if r == nil {
				return fmt.Errorf("%w: receipt for executed proposal %q missing", ErrCorruptState, proposalID)
			}
			receipt = r
			return nil
		}
		if prop.State != "passed" {
			return fmt.Errorf("%w: proposal %q is %q, not passed", ErrInvalidState, proposalID, prop.State)
		}
		if now < prop.TimelockEnd {
			return fmt.Errorf("%w: proposal %q timelock not reached (now=%d, timelock=%d)", ErrTimelock, proposalID, now, prop.TimelockEnd)
		}
		if len(prop.Actions) == 0 {
			return fmt.Errorf("%w: proposal %q has no actions", ErrInvalidAction, proposalID)
		}
		type leg struct {
			account string
			amount  int64
		}
		legs := make([]leg, 0, len(prop.Actions))
		var total int64
		for _, action := range prop.Actions {
			account, amount, err := parseAction(action)
			if err != nil {
				return fmt.Errorf("proposal %q: %w", proposalID, err)
			}
			if amount > math.MaxInt64-total {
				return fmt.Errorf("%w: transfer total overflows int64", ErrOverflow)
			}
			total += amount
			legs = append(legs, leg{account, amount})
		}
		if total > state.Treasury {
			return fmt.Errorf("%w: proposal %q needs %d, treasury has %d", ErrInsufficient, proposalID, total, state.Treasury)
		}
		receiptActions := make([]ReceiptAction, 0, len(legs))
		treasuryAfter := state.Treasury - total
		accounts := cloneAccounts(state.Accounts)
		for _, l := range legs {
			before := accounts[l.account]
			if before > math.MaxInt64-l.amount {
				return fmt.Errorf("%w: balance for account %q overflows int64", ErrOverflow, l.account)
			}
			after := before + l.amount
			receiptActions = append(receiptActions, ReceiptAction{
				Account:       l.account,
				Amount:        l.amount,
				BalanceBefore: before,
				BalanceAfter:  after,
			})
			accounts[l.account] = after
		}
		r := Receipt{
			ProposalID:     proposalID,
			ExecutedAt:     now,
			TreasuryBefore: state.Treasury,
			TreasuryAfter:  treasuryAfter,
			Actions:        receiptActions,
		}
		state.Treasury = treasuryAfter
		state.Accounts = accounts
		prop.State = "executed"
		state.Proposals[proposalID] = prop
		state.Receipts = append(state.Receipts, r)
		receipt = &r
		return nil
	})
	if err != nil {
		return nil, err
	}
	return receipt, nil
}
```

Wait — there's a subtle issue with `math.MaxInt64-total` when total could be... total is always >= 0 here. Fine. But `math.MaxInt64 - total` when total == MaxInt64 → 0, amount > 0 → overflow. Correct.

Also `state.Treasury - total`: total <= state.Treasury checked, so no underflow.

