func TestTamperedFileRejected(t *testing.T) {
	st, path := newTestStore(t, 1000)
	st.Register(passedProposal("gip-1", 0, "transfer:audits:100"))
	if _, err := st.Execute("gip-1", 1); err != nil {
		t.Fatal(err)
	}
	// tamper: drop the receipt by editing JSON (set receipts to [])
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	tampered := bytes.Replace(data, []byte(`"receipts": [`), []byte(`"receipts": [{"proposal_id":"gip-1","executed_at":1,"treasury_before":900,"treasury_after":900,"actions":[]},`), 1)
	// that makes it inconsistent; instead just blank receipts
	tampered = bytes.Replace(data, []byte(`"receipts": [`), []byte(`"receipts": [ `), 1)
	_ = tampered
	// simpler: rewrite with receipts emptied via a second replace
	tampered = bytes.Replace(data, []byte(`"receipts": [`), []byte(`"receipts": [ `), 1)
	if bytes.Equal(tampered, data) {
		t.Fatal("could not tamper")
	}
	if err := os.WriteFile(path, tampered, 0o600); err != nil {
		t.Fatal(err)
	}
	_, err = OpenStore(path)
	if !errors.Is(err, ErrCorruptState) {
		t.Fatalf("err = %v, want ErrCorruptState", err)
	}
}

