			results <- result{i, err}
		}(i)
	}
	wg.Wait()
	close(results)
	successes := 0
	for r := range results {
		if r.err == nil {
			successes++
		}
	}
	if successes != 1 {
		t.Fatalf("successes = %d, want exactly 1", successes)
	}
	treasury, _, _ := st.Balance()
	if treasury != 20000 {
		t.Fatalf("treasury = %d, want 20000", treasury)
	}
	receipts, _ := st.Receipts()
	if len(receipts) != 1 {
		t.Fatalf("receipts = %d, want 1", len(receipts))
	}
}

